def parse_duration(text: str) -> float:
    if not text or text[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    text = text[1:]  # Remove 'P'

    # Split into date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    total_seconds = 0.0

    # Parse date part (weeks or days)
    weeks = 0
    days = 0

    if date_part:
        if 'W' in date_part:
            if 'D' in date_part:
                raise ValueError("Cannot have both weeks and days")
            # Extract weeks
            if date_part.count('W') != 1:
                raise ValueError("Invalid date format")
            parts = date_part.split('W')
            if parts[1] != '':
                raise ValueError("Invalid date format")
            try:
                weeks = int(parts[0])
            except ValueError:
                raise ValueError("Invalid week value")
        elif 'D' in date_part:
            if date_part.count('D') != 1:
                raise ValueError("Invalid date format")
            parts = date_part.split('D')
            if parts[1] != '':
                raise ValueError("Invalid date format")
            try:
                days = int(parts[0])
            except ValueError:
                raise ValueError("Invalid day value")
        else:
            if date_part:
                raise ValueError("Invalid date format")

    total_seconds += weeks * 7 * 86400
    total_seconds += days * 86400

    # Parse time part (hours, minutes, seconds)
    if time_part:
        remaining = time_part

        # Parse hours
        if 'H' in remaining:
            parts = remaining.split('H', 1)
            try:
                total_seconds += int(parts[0]) * 3600
            except ValueError:
                raise ValueError("Invalid hour value")
            remaining = parts[1]

        # Parse minutes
        if 'M' in remaining:
            parts = remaining.split('M', 1)
            try:
                total_seconds += int(parts[0]) * 60
            except ValueError:
                raise ValueError("Invalid minute value")
            remaining = parts[1]

        # Parse seconds
        if 'S' in remaining:
            parts = remaining.split('S', 1)
            if parts[1] != '':
                raise ValueError("Invalid time format")
            # Handle both '.' and ',' as decimal separator
            sec_str = parts[0].replace(',', '.')
            try:
                total_seconds += float(sec_str)
            except ValueError:
                raise ValueError("Invalid second value")
            remaining = ""

        # Check for invalid characters or components
        if remaining:
            raise ValueError("Invalid time format")

    # Check that at least one component was present
    if total_seconds == 0.0 and weeks == 0 and days == 0:
        if not date_part and not time_part:
            raise ValueError("At least one component must be present")

    return total_seconds
